#include <iostream>

template <int N>
struct Factorial {
  static constexpr int value = N * Factorial<N - 1>::value;
};

template <> 
struct Factorial<0> {
  static constexpr int value = 1;
};

int main() {
  constexpr int result = Factorial<5>::value; // Compile-time calculation
  std::cout << "Factorial of 5: " << result << std::endl; 
  return 0;
}
